-- KAMOTI: area routing by barangay (SW-1)
--
-- Decision 2026-10-03: area routing is required. A report's barangay comes from
-- its pin; administrators set each staff member's barangays; the assign dialog
-- lists staff who match both the category and the barangay first, and the
-- administrator still chooses. The public board shows the barangay.
--
-- Boundaries: OpenStreetMap administrative relations (admin_level 10) for Makati's
-- 23 barangays after the 2023 EMBO transfer, retrieved 2026-10-03 through Nominatim
-- (https://nominatim.openstreetmap.org/search?q=<barangay>, Makati&format=jsonv2&polygon_geojson=1).
-- Data © OpenStreetMap contributors, ODbL 1.0 (https://www.openstreetmap.org/copyright).
-- Each is a single ring without holes, kept at full detail (1,933 points). On a 50 m
-- grid over the city boundary in src/server/lib/makati-boundary.ts, 7,484 of 7,486
-- points fall in exactly one barangay, none in two, and 2 on boundary slivers in
-- none; those take the nearest barangay.
--
-- Postgres's built-in polygon type is enough here (no PostGIS): `polygon @> point`
-- tests containment and `polygon <-> point` gives the distance, in degrees.
-- Points are (longitude, latitude).

-- ------------------------------------------------------------------ barangays

create table public.barangays (
    name     text    primary key,
    osm_id   bigint  not null,
    boundary polygon not null
);

alter table public.barangays enable row level security;
revoke all on table public.barangays from public, anon, authenticated;
grant select on table public.barangays to service_role;

