-- The barangay a point is in. A point on a boundary sliver that no polygon contains
-- takes the nearest barangay, but only within about 500 m (0.005 degrees): a pin far
-- outside the city (possible only for reports filed before the Makati check) gets
-- none rather than a wrong one.
create or replace function public.barangay_at(p_latitude double precision, p_longitude double precision)
returns text
language sql
stable
set search_path = ''
as $$
    select b.name
    from public.barangays b
    where b.boundary <-> point(p_longitude, p_latitude) < 0.005
    order by (b.boundary @> point(p_longitude, p_latitude)) desc,
             b.boundary <-> point(p_longitude, p_latitude),
             b.name
    limit 1
$$;

revoke execute on function public.barangay_at(double precision, double precision) from public, anon, authenticated;
grant execute on function public.barangay_at(double precision, double precision) to service_role;

-- ------------------------------------------------------------------ reports

alter table public.reports
    add column barangay text references public.barangays (name) on delete restrict;

create index reports_barangay_idx on public.reports (barangay);

-- Every way a report is written (the API, the fixture and demo seeds) gets its
-- barangay from the pin, and a moved pin moves it.
create or replace function public.set_report_barangay()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
    new.barangay := public.barangay_at(new.latitude, new.longitude);
    return new;
end;
$$;

create trigger reports_set_barangay
    before insert or update of latitude, longitude on public.reports
    for each row execute function public.set_report_barangay();

-- Existing reports, without touching updated_at (as in 20261003000400_workflow.sql).
alter table public.reports disable trigger reports_touch_updated_at;
update public.reports set barangay = public.barangay_at(latitude, longitude);
alter table public.reports enable trigger reports_touch_updated_at;

-- ------------------------------------------------------------------ staff areas

-- Mirrors staff_specializations: rows are switched off, never deleted.
create table public.staff_areas (
    staff_id   uuid        not null references public.profiles (id) on delete restrict,
    barangay   text        not null references public.barangays (name) on delete restrict,
    is_active  boolean     not null default true,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    primary key (staff_id, barangay)
);

create index staff_areas_barangay_idx on public.staff_areas (barangay) where is_active;

create trigger staff_areas_touch_updated_at
    before update on public.staff_areas
    for each row execute function touch_updated_at();

alter table public.staff_areas enable row level security;
revoke all on table public.staff_areas from public, anon, authenticated;
grant select, insert, update on table public.staff_areas to service_role;

-- ------------------------------------------------------------------ public board

-- The board shows each report's barangay (decision 2026-10-03). It comes from the
-- pin the board already shows. Everything above barangay is unchanged from
-- 20261003000710_public_rejection_reason.sql; new columns go at the end.
create or replace view public_reports as
select r.id,
       r.reference_code,
       r.title,
       r.description,
       c.name as category,
       r.latitude,
       r.longitude,
       r.address_text,
       r.status,
       r.submitted_at,
       r.resolved_at,
       coalesce(
           (select json_agg(json_build_object('kind', p.kind, 'storage_path', p.storage_path)
                            order by p.created_at)
            from report_photos p
            where p.report_id = r.id),
           '[]'::json
       ) as photos,
       r.category_id,
       case when r.status = 'rejected' then r.closure_reason end as rejection_reason,
       r.barangay
from reports r
join categories c on c.id = r.category_id
where r.is_public
  -- Belt and braces: a cancelled report is never public, but never publish one anyway.
  and r.status <> 'cancelled';
